from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0]); g=[row[:] for row in grid]
    dirs=((1,0),(-1,0),(0,1),(0,-1))
    zeros={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0}
    seen=set(); enclosed=[]
    for start in zeros:
        if start in seen: continue
        q=[start]; seen.add(start); comp=[]; edge=False
        while q:
            r,c=q.pop(); comp.append((r,c)); edge |= r in (0,h-1) or c in (0,w-1)
            for dr,dc in dirs:
                nr,nc=r+dr,c+dc
                if 0<=nr<h and 0<=nc<w and (nr,nc) in zeros and (nr,nc) not in seen:
                    seen.add((nr,nc));q.append((nr,nc))
        if not edge: enclosed.append(set(comp))
    # identify one components adjoining enclosed zeros
    ones={(r,c) for r in range(h) for c in range(w) if grid[r][c]==1}
    onecomp={}; comps=[]
    for s in ones:
        if s in onecomp: continue
        idx=len(comps); q=[s]; onecomp[s]=idx; comp=[]
        while q:
            r,c=q.pop();comp.append((r,c))
            for dr,dc in dirs:
                p=(r+dr,c+dc)
                if p in ones and p not in onecomp: onecomp[p]=idx;q.append(p)
        comps.append(comp)
    marked=set()
    for hole in enclosed:
        for r,c in hole:
            for dr,dc in dirs:
                p=(r+dr,c+dc)
                if p in onecomp: marked.add(onecomp[p])
    # color zero-neighbors of marked ones; inner boundary has priority 3
    for r,c in ones:
        if onecomp[(r,c)] not in marked: continue
        for dr,dc in dirs:
            p=(r+dr,c+dc)
            if 0<=p[0]<h and 0<=p[1]<w and grid[p[0]][p[1]]==0:
